import{_ as t,o as d,c as e,Q as a}from"./chunks/framework.48927342.js";const x=JSON.parse('{"title":"时间表达","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/grammar/06-time-calendar.md","filePath":"zh/more/maltese/grammar/06-time-calendar.md"}'),i={name:"zh/more/maltese/grammar/06-time-calendar.md"},r=a('<h1 id="时间表达" tabindex="-1">时间表达 <a class="header-anchor" href="#时间表达" aria-label="Permalink to &quot;时间表达&quot;">​</a></h1><p>马耳他语可以用传统口语钟点，也可以直接使用 24 小时数字时间。日常约时间时，数字写法最明确；口语表达则留意 <code>siegħa</code>（小时）及钟点数字的形式。</p><h2 id="_1-询问时间与整点" tabindex="-1">1. 询问时间与整点 <a class="header-anchor" href="#_1-询问时间与整点" aria-label="Permalink to &quot;1. 询问时间与整点&quot;">​</a></h2><ul><li><code>X&#39;ħin hu?</code>：现在几点？</li><li><code>Huwa s-sagħtejn.</code>：现在两点。</li><li><code>Hija s-siegħa.</code>：现在一点。</li><li><code>Huma t-tlieta.</code>：现在三点。</li></ul><p>常见整点说法如下。中午和午夜也常直接用 <code>nofsinhar</code>、<code>nofsillejl</code>；具体冠词和口语形式可能因语境略有不同。</p><table><thead><tr><th>时间</th><th>English</th><th>中文</th><th>常见 Malti</th></tr></thead><tbody><tr><td>01:00</td><td>one o&#39;clock</td><td>一点</td><td>is-siegħa</td></tr><tr><td>02:00</td><td>two o&#39;clock</td><td>两点</td><td>is-sagħtejn</td></tr><tr><td>03:00</td><td>three o&#39;clock</td><td>三点</td><td>it-tlieta</td></tr><tr><td>04:00</td><td>four o&#39;clock</td><td>四点</td><td>l-erbgħa</td></tr><tr><td>05:00</td><td>five o&#39;clock</td><td>五点</td><td>il-ħamsa</td></tr><tr><td>06:00</td><td>six o&#39;clock</td><td>六点</td><td>is-sitta</td></tr><tr><td>07:00</td><td>seven o&#39;clock</td><td>七点</td><td>is-sebgħa</td></tr><tr><td>08:00</td><td>eight o&#39;clock</td><td>八点</td><td>it-tmienja</td></tr><tr><td>09:00</td><td>nine o&#39;clock</td><td>九点</td><td>id-disgħa</td></tr><tr><td>10:00</td><td>ten o&#39;clock</td><td>十点</td><td>l-għaxra</td></tr><tr><td>11:00</td><td>eleven o&#39;clock</td><td>十一点</td><td>il-ħdax</td></tr><tr><td>12:00</td><td>noon / midnight</td><td>中午/午夜</td><td>nofsinhar / nofsillejl</td></tr></tbody></table><p>提问时可用 <code>X&#39;ħin hu?</code>。回答时可说钟点词，也可说数字时间，例如 <code>Huwa s-sagħtejn.</code>（两点）或 <code>Huwa 14:00.</code>（14:00）。</p><h2 id="_2-早上、下午、晚上与相对时间" tabindex="-1">2. 早上、下午、晚上与相对时间 <a class="header-anchor" href="#_2-早上、下午、晚上与相对时间" aria-label="Permalink to &quot;2. 早上、下午、晚上与相对时间&quot;">​</a></h2><table><thead><tr><th>中文</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>早晨</td><td>morning</td><td>filgħodu</td></tr><tr><td>上午</td><td>morning; before noon</td><td>filgħodu</td></tr><tr><td>中午</td><td>midday</td><td>nofsinhar</td></tr><tr><td>下午</td><td>afternoon</td><td>wara nofsinhar</td></tr><tr><td>晚上</td><td>evening</td><td>filgħaxija</td></tr><tr><td>夜里</td><td>night</td><td>billejl</td></tr><tr><td>今天</td><td>today</td><td>illum</td></tr><tr><td>明天</td><td>tomorrow</td><td>għada</td></tr><tr><td>昨天</td><td>yesterday</td><td>ilbieraħ</td></tr><tr><td>后天</td><td>day after tomorrow</td><td>pitgħada</td></tr><tr><td>现在</td><td>now</td><td>issa</td></tr><tr><td>上周</td><td>last week</td><td>il-ġimgħa li għaddiet</td></tr><tr><td>本周/这周</td><td>this week</td><td>din il-ġimgħa</td></tr><tr><td>下周</td><td>next week</td><td>il-ġimgħa d-dieħla</td></tr><tr><td>上个月</td><td>last month</td><td>ix-xahar li għadda</td></tr><tr><td>本月/这个月</td><td>this month</td><td>dan ix-xahar</td></tr><tr><td>下个月</td><td>next month</td><td>ix-xahar id-dieħel</td></tr><tr><td>去年</td><td>last year</td><td>is-sena l-oħra</td></tr><tr><td>今年</td><td>this year</td><td>din is-sena</td></tr><tr><td>明年</td><td>next year</td><td>is-sena d-dieħla</td></tr></tbody></table><p>表达具体时刻时，可在时间短语后加时段：<code>fit-07:15 ta&#39; filgħodu</code>（早上 07:15）、<code>fl-14:30 ta&#39; wara nofsinhar</code>（下午 14:30）、<code>fit-20:45 ta&#39; filgħaxija</code>（晚上 20:45）。</p><h2 id="_3-几点几分" tabindex="-1">3. 几点几分 <a class="header-anchor" href="#_3-几点几分" aria-label="Permalink to &quot;3. 几点几分&quot;">​</a></h2><p><code>u</code> 表示“和/过”，用于整点后经过的分钟：<code>it-tlieta u għaxar minuti</code>（三点过十分）。<code>nofs</code> 表示“半”，如 <code>it-tlieta u nofs</code>（三点半）。<code>neqsin</code> 是 <code>nieqes</code>（少、差）的复数形式，用“下一小时 + neqsin + 分钟”表达差几分到下一点：<code>it-tlieta neqsin kwart</code>（差一刻三点，即 2:45）。非整刻时间用数字时间最清楚；在时间前通常加 <code>f&#39;</code>，并按拼写习惯与冠词缩合。</p><ul><li><code>it-tlieta u kwart</code>：三点一刻（3:15）</li><li><code>it-tlieta u nofs</code>：三点半（3:30）</li><li><code>it-tlieta neqsin kwart</code>：差一刻三点（2:45）</li><li><code>l-erbgħa neqsin għaxar minuti</code>：差十分四点（3:50）</li><li><code>fit-08:15</code>：在 08:15</li><li><code>fit-14:30</code>：在 14:30</li><li><code>fit-18:45</code>：在 18:45</li></ul><p>表示“几点几分”时，先说整点再补分钟；若不确定传统口语形式，可直接使用 24 小时制数字。正式约会、车票和行程安排也推荐数字写法。</p><h2 id="_4-20-个时刻表达" tabindex="-1">4. 20 个时刻表达 <a class="header-anchor" href="#_4-20-个时刻表达" aria-label="Permalink to &quot;4. 20 个时刻表达&quot;">​</a></h2><p>以下是时间值和时刻短语，不使用完整句子。用 <code>ta&#39; filgħodu</code>、<code>ta&#39; wara nofsinhar</code>、<code>ta&#39; filgħaxija</code> 标出早、午、晚；需要避免歧义时可用 24 小时制。</p><table><thead><tr><th style="text-align:right;">#</th><th>中文时刻</th><th>English time</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>凌晨一点</td><td>1:00 a.m.</td><td>is-siegħa ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">2</td><td>早上七点</td><td>7:00 a.m.</td><td>is-sebgħa ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">3</td><td>早上八点一刻</td><td>8:15 a.m.</td><td>it-tmienja u kwart ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">4</td><td>早上八点半</td><td>8:30 a.m.</td><td>it-tmienja u nofs ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">5</td><td>早上八点四十五分</td><td>8:45 a.m.</td><td>id-disgħa neqsin kwart ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">6</td><td>早上九点过十分</td><td>9:10 a.m.</td><td>id-disgħa u għaxar minuti ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">7</td><td>上午十点差五分</td><td>9:55 a.m.</td><td>l-għaxra neqsin ħames minuti ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">8</td><td>上午十一点二十分</td><td>11:20 a.m.</td><td>il-ħdax u għoxrin minuta ta&#39; filgħodu</td></tr><tr><td style="text-align:right;">9</td><td>中午十二点</td><td>12:00 noon</td><td>nofsinhar</td></tr><tr><td style="text-align:right;">10</td><td>下午一点一刻</td><td>1:15 p.m.</td><td>is-siegħa u kwart ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">11</td><td>下午两点半</td><td>2:30 p.m.</td><td>is-sagħtejn u nofs ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">12</td><td>下午两点四十五分</td><td>2:45 p.m.</td><td>it-tlieta neqsin kwart ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">13</td><td>下午三点过十分</td><td>3:10 p.m.</td><td>it-tlieta u għaxar minuti ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">14</td><td>下午四点差十分</td><td>3:50 p.m.</td><td>l-erbgħa neqsin għaxar minuti ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">15</td><td>下午五点二十分</td><td>5:20 p.m.</td><td>il-ħamsa u għoxrin minuta ta&#39; wara nofsinhar</td></tr><tr><td style="text-align:right;">16</td><td>傍晚六点整</td><td>6:00 p.m.</td><td>is-sitta ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">17</td><td>晚上七点一刻</td><td>7:15 p.m.</td><td>is-sebgħa u kwart ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">18</td><td>晚上八点半</td><td>8:30 p.m.</td><td>it-tmienja u nofs ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">19</td><td>晚上九点差五分</td><td>8:55 p.m.</td><td>id-disgħa neqsin ħames minuti ta&#39; filgħaxija</td></tr><tr><td style="text-align:right;">20</td><td>午夜十二点</td><td>12:00 midnight</td><td>nofsillejl</td></tr></tbody></table><h2 id="_5-时间长度表达" tabindex="-1">5. 时间长度表达 <a class="header-anchor" href="#_5-时间长度表达" aria-label="Permalink to &quot;5. 时间长度表达&quot;">​</a></h2><p>表示“持续多久”时，可用 <code>għal + 时长</code> 表示“持续/有……之久”；也可用 <code>idum</code>（历时、持续）直接说明一件事需要多久。分钟通常用 <code>minuta/minuti</code>；<code>kwarta</code> 表示一刻钟，<code>nofs siegħa</code> 表示半小时；<code>sagħtejn</code> 是“两小时”的常见双数形式，多个小时也可用 <code>sigħat</code>。两天可说 <code>jumejn</code>。</p><table><thead><tr><th style="text-align:right;">#</th><th>中文时长</th><th>English duration</th><th>Malti</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>一分钟</td><td>one minute</td><td>minuta</td></tr><tr><td style="text-align:right;">2</td><td>两分钟</td><td>two minutes</td><td>żewġ minuti</td></tr><tr><td style="text-align:right;">3</td><td>五分钟</td><td>five minutes</td><td>ħames minuti</td></tr><tr><td style="text-align:right;">4</td><td>十分钟</td><td>ten minutes</td><td>għaxar minuti</td></tr><tr><td style="text-align:right;">5</td><td>一刻钟</td><td>a quarter of an hour</td><td>kwart ta&#39; siegħa</td></tr><tr><td style="text-align:right;">6</td><td>一刻钟</td><td>a quarter of an hour</td><td>kwarta</td></tr><tr><td style="text-align:right;">7</td><td>半小时</td><td>half an hour</td><td>nofs siegħa</td></tr><tr><td style="text-align:right;">8</td><td>一小时</td><td>one hour</td><td>siegħa</td></tr><tr><td style="text-align:right;">9</td><td>两小时</td><td>two hours</td><td>sagħtejn</td></tr><tr><td style="text-align:right;">10</td><td>三小时</td><td>three hours</td><td>tliet sigħat</td></tr><tr><td style="text-align:right;">11</td><td>四小时</td><td>four hours</td><td>erba&#39; sigħat</td></tr><tr><td style="text-align:right;">12</td><td>几小时</td><td>a few hours</td><td>ftit sigħat</td></tr><tr><td style="text-align:right;">13</td><td>一天</td><td>one day</td><td>jum wieħed</td></tr><tr><td style="text-align:right;">14</td><td>两天</td><td>two days</td><td>jumejn</td></tr><tr><td style="text-align:right;">15</td><td>三天</td><td>three days</td><td>tlett ijiem</td></tr><tr><td style="text-align:right;">16</td><td>一周</td><td>one week</td><td>ġimgħa</td></tr><tr><td style="text-align:right;">17</td><td>两周</td><td>two weeks</td><td>żewġ ġimgħat</td></tr><tr><td style="text-align:right;">18</td><td>三周</td><td>three weeks</td><td>tliet ġimgħat</td></tr><tr><td style="text-align:right;">19</td><td>一个月</td><td>one month</td><td>xahar</td></tr><tr><td style="text-align:right;">20</td><td>一年</td><td>one year</td><td>sena</td></tr></tbody></table>',20),l=[r];function o(n,s,g,h,c,m){return d(),e("div",null,l)}const f=t(i,[["render",o]]);export{x as __pageData,f as default};
